mapper.update:
update staff_performance_personnel set
show_state = #{showState,jdbcType=INTEGER},back_state = #{backState,jdbcType=INTEGER}
where staff_performance_id = #{staffPerformanceId,jdbcType=BIGINT}

    and back_state = #{oldBackState,jdbcType=INTEGER}


    and show_state = #{oldShowState,jdbcType=INTEGER}

;

update staff_performance_personnel set
boss_opinion = null
where staff_performance_id = #{staffPerformanceId,jdbcType=BIGINT};

mapper.select:
select a.*
from staff_performance_personnel a
left join bus_user_role b on a.user_id = b.user_id
where staff_performance_id = #{staffPerformanceId,jdbcType=BIGINT}
and b.role_id= 50 and a.delete_flag = 0
;
